$destinations=$pdo->query("SELECT DISTINCT destination FROM locations WHERE destination IS NOT NULL AND destination<>'' ORDER BY destination")->fetchAll(PDO::FETCH_COLUMN);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$destination=trim($_POST['destination']??'');$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$budget=(float)($_POST['budget']??0);$desc=trim($_POST['description']??'');if(!$name||!$destination||!$start||!$end||$budget<0)$error='Vui lòng nhập đầy đủ thông tin.';elseif(!in_array($destination,$destinations,true))$error='Vui lòng chọn điểm đến có trong danh sách.';elseif($end<$start)$error='Ngày kết thúc phải sau ngày bắt đầu.';if(!$error){$st=$pdo->prepare('INSERT INTO trips(owner_id,name,destination,start_date,end_date,budget,description,status) VALUES(?,?,?,?,?,?,?,\'draft\')');$st->execute([$_SESSION['user']['id'],$name,$destination,$start,$end,$budget,$desc]);$id=$pdo->lastInsertId();$pdo->prepare('INSERT INTO trip_members(trip_id,user_id,member_role) VALUES(?,?,\'owner\')')->execute([$id,$_SESSION['user']['id']]);flash('success','Tạo chuyến đi thành công.');redirect('user/trip-detail.php?id='.$id);}}
